//! Platform shaders generated from the one canonical `orb.frag`.
//!
//! - Android (OpenGL ES 2/3): the canonical GLSL ES 1.00 source, verbatim
//!   after a fingerprint header.
//! - iOS (Metal): MSL produced by naga from a mechanical rewrite of the
//!   canonical source (uniform block, output variable, y-up fragment
//!   coordinate). No Metal is written by hand.
//!
//! Every generated file starts with [`header`], which records the SHA-256 of
//! the canonical source; [`verify`] rejects stale or hand-edited copies.
//! Generated files are build outputs and are never committed; [`lint`]
//! enforces that for a repository's tracked files.
use notdot_orb::contract::{self, BLOCK_MAPPING, BLOCK_VEC4S, UNIFORMS};
use std::fmt;

/// Repository path of the canonical shader.
pub const CANONICAL_PATH: &str = "crates/notdot-orb/src/orb.frag";
/// The website keeps a synced copy (scripts/sync_brand_assets.py). It must
/// stay byte-identical to the canonical source.
pub const SYNCED_COPIES: [&str; 1] = ["docs/site-assets/orb.frag"];
const MARKER: &str = "GENERATED by notdot-orb-gen";
/// Distinctive lines of the canonical shader, used to find hand copies.
const SIGNATURES: [&str; 2] = [
    "float band(float value, float width)",
    "uniform float task_strength",
];

#[derive(Debug)]
pub enum Error {
    /// The rewrite for naga did not find an expected construct.
    Rewrite(&'static str),
    Parse(String),
    Validate(String),
    Write(String),
    Header(String),
}
impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Rewrite(what) => write!(f, "cannot rewrite orb.frag: {what}"),
            Self::Parse(e) => write!(f, "naga could not parse the rewritten shader: {e}"),
            Self::Validate(e) => write!(f, "naga validation failed: {e}"),
            Self::Write(e) => write!(f, "naga could not write MSL: {e}"),
            Self::Header(e) => write!(f, "generated shader header: {e}"),
        }
    }
}
impl std::error::Error for Error {}

/// Fingerprint header for a generated file, using `//` comments, which
/// GLSL and MSL share.
pub fn header() -> String {
    format!(
        "// {MARKER} from {CANONICAL_PATH}. Do not edit; do not commit.\n\
         // orb.frag sha256={} contract={}\n",
        contract::shader_sha256(),
        contract::ORB_CONTRACT_VERSION
    )
}

/// Check that `generated` carries the header for the current canonical
/// source and contract version.
pub fn verify(generated: &str) -> Result<(), Error> {
    let expected = header();
    if generated.starts_with(&expected) {
        Ok(())
    } else if generated.contains(MARKER) {
        Err(Error::Header(
            "stale: regenerate from the current orb.frag".into(),
        ))
    } else {
        Err(Error::Header(
            "missing; this is not a generated copy".into(),
        ))
    }
}

/// Android: the canonical GLSL ES 1.00 source, unchanged, after the header.
pub fn glsl_es() -> String {
    header() + contract::FRAGMENT_SHADER
}

/// The canonical fragment shader rewritten to Vulkan-style GLSL 4.50, which
/// naga's GLSL front end accepts. Only declarations and two built-ins change:
/// loose uniforms become `#define`s into one uniform block laid out as
/// `contract::BLOCK_MAPPING`; `gl_FragColor` becomes an output variable; and
/// `gl_FragCoord` is read with a bottom-left origin, as in OpenGL, because
/// Metal's fragment position starts at the top left.
pub fn vulkan_glsl() -> Result<String, Error> {
    let source = contract::FRAGMENT_SHADER;
    let mut body = String::new();
    let mut uniforms = Vec::new();
    for line in source.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix("uniform ") {
            let name = rest
                .trim_end_matches(';')
                .split_whitespace()
                .nth(1)
                .ok_or(Error::Rewrite("uniform without a name"))?;
            uniforms.push(name.to_owned());
            continue;
        }
        body.push_str(line);
        body.push('\n');
    }
    if uniforms != UNIFORMS {
        return Err(Error::Rewrite("uniforms differ from contract::UNIFORMS"));
    }
    let main = "void main() {";
    if body.matches(main).count() != 1 || !body.contains("gl_FragColor") {
        return Err(Error::Rewrite(
            "expected one `void main() {` and gl_FragColor",
        ));
    }
    let body = body
        .replace("gl_FragColor", "notdot_frag_color")
        .replace("gl_FragCoord", "notdot_frag_coord")
        .replace(
            main,
            &format!(
                "{main}\n        vec4 notdot_frag_coord = vec4(gl_FragCoord.x, resolution.y - gl_FragCoord.y, gl_FragCoord.zw);"
            ),
        );
    let mut out = String::from("#version 450\n");
    out.push_str("layout(set = 0, binding = 0) uniform NotdotOrb {");
    for index in 0..BLOCK_VEC4S {
        out.push_str(&format!(" vec4 u{index};"));
    }
    out.push_str(" };\n");
    for (name, swizzle) in BLOCK_MAPPING {
        out.push_str(&format!("#define {name} {swizzle}\n"));
    }
    out.push_str("layout(location = 0) out vec4 notdot_frag_color;\n");
    out.push_str(&body);
    Ok(out)
}

/// The canonical vertex shader rewritten for naga in the same way.
pub fn vulkan_vertex_glsl() -> Result<String, Error> {
    let source = contract::VERTEX_SHADER;
    let rewritten = source.replacen(
        "attribute vec2 position;",
        "layout(location = 0) in vec2 position;",
        1,
    );
    if rewritten == source {
        return Err(Error::Rewrite("vertex shader has no `position` attribute"));
    }
    Ok(format!("#version 450\n{rewritten}\n"))
}

/// Metal shading language for one stage, plus the generated function name.
pub struct Msl {
    pub source: String,
    pub entry_point: String,
}

/// Metal function names, distinct so both stages link into one library.
pub const MSL_FRAGMENT_FUNCTION: &str = "notdot_orb_fragment";
pub const MSL_VERTEX_FUNCTION: &str = "notdot_orb_vertex";

fn translate(source: &str, stage: naga::ShaderStage, name: &str) -> Result<Msl, Error> {
    let mut module = naga::front::glsl::Frontend::default()
        .parse(&naga::front::glsl::Options::from(stage), source)
        .map_err(|e| Error::Parse(e.emit_to_string(source)))?;
    match module.entry_points.as_mut_slice() {
        [entry] => entry.name = name.to_owned(),
        _ => return Err(Error::Rewrite("expected exactly one entry point")),
    }
    let info = naga::valid::Validator::new(
        naga::valid::ValidationFlags::all(),
        naga::valid::Capabilities::empty(),
    )
    .validate(&module)
    .map_err(|e| Error::Validate(e.emit_to_string(source)))?;
    let options = naga::back::msl::Options {
        lang_version: (2, 1),
        fake_missing_bindings: false,
        per_entry_point_map: [(
            name.to_owned(),
            naga::back::msl::EntryPointResources {
                resources: [(
                    naga::ResourceBinding {
                        group: 0,
                        binding: 0,
                    },
                    naga::back::msl::BindTarget {
                        buffer: Some(0),
                        ..Default::default()
                    },
                )]
                .into_iter()
                .collect(),
                ..Default::default()
            },
        )]
        .into_iter()
        .collect(),
        ..Default::default()
    };
    let (source, translation) = naga::back::msl::write_string(
        &module,
        &info,
        &options,
        &naga::back::msl::PipelineOptions::default(),
    )
    .map_err(|e| Error::Write(e.to_string()))?;
    let entry_point = translation
        .entry_point_names
        .into_iter()
        .next()
        .ok_or(Error::Write("no entry point".into()))?
        .map_err(|e| Error::Write(e.to_string()))?;
    Ok(Msl {
        source: header() + &source,
        entry_point,
    })
}

/// iOS fragment stage. Bind 16 floats from `Uniforms::block` at
/// `[[buffer(0)]]`; the output is premultiplied RGBA.
pub fn msl_fragment() -> Result<Msl, Error> {
    translate(
        &vulkan_glsl()?,
        naga::ShaderStage::Fragment,
        MSL_FRAGMENT_FUNCTION,
    )
}

/// iOS vertex stage: `contract::QUAD` as float2 vertex attribute 0.
pub fn msl_vertex() -> Result<Msl, Error> {
    translate(
        &vulkan_vertex_glsl()?,
        naga::ShaderStage::Vertex,
        MSL_VERTEX_FUNCTION,
    )
}

/// One lint finding.
#[derive(Debug, PartialEq, Eq)]
pub struct Violation {
    pub path: String,
    pub reason: &'static str,
}

/// Check tracked files (repository-relative path, contents) for hand
/// copies of the shader, committed generated output, or a stale synced copy.
pub fn lint<'a>(files: impl IntoIterator<Item = (&'a str, &'a [u8])>) -> Vec<Violation> {
    let canonical = contract::FRAGMENT_SHADER.as_bytes();
    let mut violations = Vec::new();
    for (path, contents) in files {
        if path == CANONICAL_PATH {
            continue;
        }
        let text = String::from_utf8_lossy(contents);
        let mut flag = |reason| {
            violations.push(Violation {
                path: path.to_owned(),
                reason,
            })
        };
        if SYNCED_COPIES.contains(&path) {
            if contents != canonical {
                flag("synced copy differs from orb.frag; run scripts/sync_brand_assets.py");
            }
            continue;
        }
        // This crate names the marker and signatures in order to find them.
        if path.starts_with("crates/notdot-orb-gen/") {
            continue;
        }
        if text.contains(MARKER) {
            flag("generated shader is committed; generate it at build time");
        } else if SIGNATURES.iter().any(|signature| text.contains(signature)) {
            flag("hand copy of orb.frag; use the canonical file or a generated adapter");
        } else if [".metal", ".agsl"].iter().any(|ext| path.ends_with(ext)) {
            flag("shader source outside the canonical orb pipeline");
        }
    }
    violations
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn android_copy_is_the_canonical_source_after_the_header() {
        let generated = glsl_es();
        verify(&generated).unwrap();
        assert_eq!(
            generated.strip_prefix(&header()).unwrap(),
            contract::FRAGMENT_SHADER
        );
    }

    #[test]
    fn metal_translation_validates_and_binds_the_contract_block() {
        let fragment = msl_fragment().unwrap();
        verify(&fragment.source).unwrap();
        assert!(
            fragment.source.contains("[[buffer(0)]]"),
            "{}",
            fragment.source
        );
        assert!(fragment.source.contains("fragment "));
        let vertex = msl_vertex().unwrap();
        verify(&vertex.source).unwrap();
        assert!(vertex.source.contains("vertex "));
        assert!(vertex.source.contains("[[attribute(0)]]"));
        assert_eq!(fragment.entry_point, MSL_FRAGMENT_FUNCTION);
        assert_eq!(vertex.entry_point, MSL_VERTEX_FUNCTION);
    }

    #[test]
    fn rewrite_keeps_every_canonical_statement() {
        let rewritten = vulkan_glsl().unwrap();
        for line in contract::FRAGMENT_SHADER.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with("uniform ") || line == "void main() {" {
                continue;
            }
            let expected = line
                .replace("gl_FragColor", "notdot_frag_color")
                .replace("gl_FragCoord", "notdot_frag_coord");
            assert!(rewritten.contains(&expected), "lost: {line}");
        }
    }

    #[test]
    fn verify_rejects_stale_and_foreign_sources() {
        assert!(matches!(verify("void main(){}"), Err(Error::Header(_))));
        let stale = header().replace(&contract::shader_sha256(), &"0".repeat(64));
        assert!(matches!(verify(&(stale + "x")), Err(Error::Header(e)) if e.contains("stale")));
    }

    #[test]
    fn lint_flags_copies_generated_output_and_drift() {
        let canonical = contract::FRAGMENT_SHADER.as_bytes();
        let generated = glsl_es();
        let edited = contract::FRAGMENT_SHADER.replace(".17", ".18");
        let files: Vec<(&str, &[u8])> = vec![
            (CANONICAL_PATH, canonical),
            ("docs/site-assets/orb.frag", canonical),
            ("mobile/ios/Orb.metal", b"fragment float4 f() {}"),
            (
                "mobile/android/app/src/main/assets/orb.frag",
                generated.as_bytes(),
            ),
            ("mobile/android/Orb.kt", edited.as_bytes()),
            ("README.md", b"The orb lives in orb.frag."),
        ];
        let paths: Vec<_> = lint(files).into_iter().map(|v| v.path).collect();
        assert_eq!(
            paths,
            [
                "mobile/ios/Orb.metal",
                "mobile/android/app/src/main/assets/orb.frag",
                "mobile/android/Orb.kt"
            ]
        );
        let stale: Vec<(&str, &[u8])> = vec![("docs/site-assets/orb.frag", b"old")];
        assert_eq!(lint(stale).len(), 1);
    }
}
